import{z as i,x as B,o as e,c as l,q as A,j as n,D as a,d as o,s as t,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"机制设计的视角","description":"","frontmatter":{"title":"机制设计的视角","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-mechanism-design.md","filePath":"llm/sgt-mechanism-design.md","lastUpdated":1791063341000}'),d={name:"llm/sgt-mechanism-design.md"};function p(h,E,C,g,m,c){const r=B("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="机制设计的视角" tabindex="-1">机制设计的视角 <a class="header-anchor" href="#机制设计的视角" aria-label="Permalink to &quot;机制设计的视角&quot;">​</a></h1><div class="epigraph"><p>前面的课都在给定博弈里求胜，机制设计倒过来问：规则怎么定，才能让自利的均衡恰好落在想要的地方。</p><footer>—— 据 Hurwicz, The Design of Mechanisms for Resource Allocation, 1973；Myerson, Optimal Auction Design, 1981 整理</footer></div><p><a href="/llm/sgt-negotiation">上一课</a>把协商读成「协议如何自发长出」，结尾留了一句：协议形成是规则设计的特例。本课完成这次视角翻转——从参与者换成规则制定者。这是收束单元的第一课：前九课训练的都是「在博弈里学习的人」，本课训练「设计博弈的人」，而每一个部署语言模型的工程师，其实是后者。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机制设计的定义性动作：给定目标（效率、收益、真实汇报），<strong>反推</strong>交互规则，使得参与者各自最大化自身利益时的均衡结局恰好实现目标。Hurwicz 1973 把「机制」形式化为信息空间与结局规则的组合；Vickrey 1961 的二价拍卖是原型示范：让每个竞拍者报真实估值成为占优策略（报高了可能付亏，报低了可能白丢），激励相容由此得名。Myerson 1981 把拍卖设计推到收益最优的解析解。这一传统的全部力量在于<strong>不依赖参与者的善意</strong>：它不问「怎么让模型诚实」，而问「什么规则下连不诚实的模型也产生诚实的结果」。</p><p><span class="marginnote">二价拍卖翻译成大白话：价高者得，但只按第二名的报价付钱。这时虚报没有好处——报高了可能付冤枉价，报低了可能白丢东西，如实报价永远不亏。「激励相容」说的就是这种设计：规则让说真话恰好也是对自己最有利的做法。</span></p><p>对语言模型系统，缺口立刻显形。训练视角把失真当「模型学坏」：奖励黑客是训练问题，谄媚是训练问题。机制视角把这些重读为<strong>规则问题</strong>：评测把单一公开排行榜当唯一信号，模型自然过拟合排行榜；多 Agent 系统里模型互相评审而不设披露规则，评审共谋是均衡不是意外；用户反馈在线学习里，讨好短期反馈的策略占优——主干课在<a href="/llm/reward-hacking-llm">奖励黑客</a>处按训练病处理的对象，在这里拿到第二个诊断：判据的激励结构设计错了，再训也白训。</p><h3 id="最坏情况与均衡质量" tabindex="-1">最坏情况与均衡质量 <a class="header-anchor" href="#最坏情况与均衡质量" aria-label="Permalink to &quot;最坏情况与均衡质量&quot;">​</a></h3><p>机制设计给出两个语言系统直接可用的量。其一，激励相容检查：对每个参与者、每组他人行为，验证「真实汇报/诚实行动」是否不劣于任何偏离——对模型评测而言，这意味着测试「策略性夸大成绩」是否真的无利可图，而不是假设模型不会想到。其二，无政府代价（price of anarchy，Koutsoupias 与 Papadimitriou 1999）：均衡结局与最优结局之比的最坏值。Roughgarden 与 Tardos 2002 对自私路由的答案是仿射时延下均衡总成本至多是最优的 \\(4/3\\) 倍——这是把「分散自利最坏会差多少」变成<strong>可算的数</strong>的示范。多模型路由、多 Agent 分工都可以做同型的最坏比分析：不这么做，就只能在事故后宣布「没想到它们会这样互动」。</p><p><span class="marginnote">数字实例：把 4/3 倍读成堵车版——若所有人听指挥走最优路线总耗时 30 分钟，各自抄近道的均衡下总耗时最坏 40 分钟；多出的 10 分钟就是「没人指挥的代价」的账面值。无政府代价做的就是把这笔账从「感觉会乱」变成一个可比较的数。</span></p><p><span class="marginnote">Vickrey 1961 的二价拍卖与 eBay 时代的实际拍卖机制之间隔着几十年的机制工程；LLM 评测从「排行榜」到「不可博弈的评测」之间，目前普遍还停在 Vickrey 之前。</span></p>',11)),(e(),n(s,null,{default:a(()=>[t(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E7%A4%BE%E4%BC%9A%E7%9B%AE%E6%A0%87%EF%BC%9A%E6%95%88%E7%8E%87%2F%E7%9C%9F%E5%AE%9E%2F%E5%85%AC%E5%B9%B3%22%5D%20--%3E%20INV%5B%22%E5%8F%8D%E6%8E%A8%E8%A7%84%E5%88%99%EF%BC%9A%E6%BF%80%E5%8A%B1%E7%9B%B8%E5%AE%B9%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20INV%20--%3E%20MECH%5B%22%E6%9C%BA%E5%88%B6%EF%BC%9A%E4%BF%A1%E6%81%AF%E7%A9%BA%E9%97%B4%20%2B%20%E7%BB%93%E5%B1%80%E8%A7%84%E5%88%99%22%5D%0A%20%20MECH%20--%3E%20EQM%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E8%87%AA%E5%88%A9%E5%9D%87%E8%A1%A1%22%5D%0A%20%20EQM%20--%3E%20OK%7B%22%E5%9D%87%E8%A1%A1%3D%E7%9B%AE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20IMPL%5B%22%E9%83%A8%E7%BD%B2%EF%BC%9A%E6%9C%BA%E5%88%B6%E6%9B%BF%E4%BF%A1%E4%BB%BB%E8%83%8C%E4%B9%A6%22%5D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20POA%5B%22%E6%B5%8B%E6%97%A0%E6%94%BF%E5%BA%9C%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%9C%80%E5%9D%8F%E6%AF%94%22%5D%0A%20%20POA%20--%3E%20MECH%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>视角反转加两个可算量</strong>：把问题从「怎么让模型诚实」反转为「什么规则下连不诚实的参与者也产生诚实的结果」，工具取激励相容检查（逐参与者验证真实汇报无利可图）与无政府代价（均衡与最优结局的最坏比），后者把「分散自利最坏差多少」变成一个数。三个落点——评测机制、多 Agent 协作规则、计算可行的机制——按「改收益矩阵而非改权重」归位。本课只搬概念与原型结论，不证明定理。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么「设计规则」能解决「训练调不动」的问题？因为机制改变了博弈的收益矩阵，而收益矩阵决定均衡——上一单元的全部动力学都在矩阵给定的前提下运行，机制设计动的是矩阵本身。对 LLM 的三个落点：<strong>评测机制</strong>——报告方式从单一公开榜改为可复用留出集、变换测度与加噪（Dwork 等 2015 的 reusable holdout 正是为「自适应数据分析下保住统计效度」设计的机制），主干<a href="/llm/rlhf-pipeline">RLHF 流程</a>里的偏好比较也可同样处理标注者激励；<strong>多 Agent 协作机制</strong>——评审披露、轮换裁判、押注式承诺，直接对应上一课协商边界处「没有第三条路」的缺口；<strong>Nisan 与 Ronen 1999</strong> 的算法机制设计给出计算侧约束：机制本身要在多项式时间内可执行，规则太复杂就等于没规则。</p><p>机制设计的边界与自博弈的边界在此合流：机制可以改收益矩阵，不能改参与者的能力差；均衡仍受上一单元的非传递与循环制约；且机制本身是新的可对策对象——参与者对规则过拟合，Goodhart 在规则层面重演。</p><p>这张图回答的问题是：不改权重、只改收益矩阵，均衡怎么从「共谋」被挪到「诚实」。</p>',6)),(e(),n(s,null,{default:a(()=>[t(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E8%A7%84%E5%88%99%EF%BC%9A%E5%8D%95%E4%B8%80%E5%85%AC%E5%BC%80%E6%8E%92%E8%A1%8C%E6%A6%9C%22%5D%20--%3E%20INC%5B%22%E5%A4%B8%E5%A4%A7%E6%88%90%E7%BB%A9%E6%9C%89%E5%9B%9E%E6%8A%A5%22%5D%0A%20%20INC%20--%3E%20BAD%5B%22%E5%9D%87%E8%A1%A1%EF%BC%9A%E8%BF%87%E6%8B%9F%E5%90%88%E6%A6%9C%E5%8D%95%E4%B8%8E%E8%AF%84%E5%AE%A1%E5%85%B1%E8%B0%8B%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%9C%BA%E5%88%B6%EF%BC%9A%E7%95%99%E5%87%BA%E9%9B%86%E3%80%81%E8%BD%AE%E6%8D%A2%E8%A3%81%E5%88%A4%E3%80%81%E6%8A%A5%E5%91%8A%E5%8A%A0%E5%99%AA%22%5D%20--%3E%20DEC%5B%22%E7%9C%9F%E5%AE%9E%E6%B1%87%E6%8A%A5%E6%9B%B4%E5%88%92%E7%AE%97%22%5D%0A%20%20DEC%20--%3E%20GOOD%5B%22%E5%9D%87%E8%A1%A1%EF%BC%9A%E8%AF%9A%E5%AE%9E%E8%A1%8C%E4%B8%BA%22%5D%0A%20%20GOOD%20--%3E%20COST%5B%22%E7%BA%A6%E6%9D%9F%EF%BC%9A%E6%9C%BA%E5%88%B6%E6%9C%AC%E8%BA%AB%E9%A1%BB%E5%A4%9A%E9%A1%B9%E5%BC%8F%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只搬运概念与原型结论，不证明定理：激励相容的完整刻画（显示原理）、最优机制的解析解、无政府代价的逐域计算，都是专门文献的事（Nisan 等 2007 的教科书卷给出入口）。</p><p><span class="marginnote">常见误区：以为机制设计就是「定个惩罚条款」。它的核心是改收益矩阵，让自利者自发走向目标，而不是靠事后抓违规——惩罚太重会催生规避行为，规则太复杂参与者算不清，等于没规则（这正是 Nisan 与 Ronen 计算可行约束的用意）。</span> 对语言系统，机制设计还有一处未定空档：经典理论假设参与者是理性的固定效用最大化者，而 LLM 的「效用」是训练出来的、可塑的——机制可以<strong>内化</strong>进权重，也意味着均衡分析要搭在「训练后模型近似最优响应」的假设上，其误差界目前没有成熟结果。规则写进权重还是写在环境里，是本课程留下的双轨开放题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机制设计反推规则使自利均衡落在目标处；激励相容是核心约束（Vickrey 1961、Myerson 1981）。</li><li>训练视角的「模型学坏」可重读为规则问题：排行榜过拟合、评审共谋、反馈谄媚都是激励结构病。</li><li>无政府代价把「自利最坏差多少」变成可算的数（Koutsoupias 与 Papadimitriou 1999；Roughgarden 与 Tardos 2002）。</li><li>落点三处：评测机制、多 Agent 协作规则、计算可行的机制（Nisan 与 Ronen 1999）。</li><li>机制本身也会被过拟合（Goodhart 的规则层版本），且 LLM 的效用可塑使均衡分析添新空档。</li><li>出处：Hurwicz 1973；Vickrey 1961；Myerson 1981；Nisan 与 Ronen 1999；Koutsoupias 与 Papadimitriou 1999；Roughgarden 与 Tardos 2002。</li></ul>',5))])}const _=i(d,[["render",p]]);export{D as __pageData,_ as default};
